const raw = $input.item.json;
const aiText = raw.output[0].content[0].text;
const aiData = JSON.parse(aiText.replace(/```json|```/g, '').trim());

const contexto = $('Preparar Contexto Avisos').item.json;
const forceInternal = contexto.force_internal === true;
const is2500 = contexto.is_2500 === true;
const hasDamage = contexto.has_damage === true;
const numeroAvisos = contexto.numero_avisos || 1;
const clientCode = String(contexto.client_center_code || '');

// Decision values with fallbacks for flat JSON structures
let targetType = aiData.decision?.target_type || aiData.target_type || 'standard';
if (forceInternal || is2500) targetType = 'internal';

// CRITICO: si es forceInternal, siempre debe ser shouldNotify true
const shouldNotify = aiData.decision?.should_notify === true || aiData.should_notify === true || forceInternal;

const subject = aiData.decision?.email_subject || aiData.email_subject || (is2500 ? `Devolucion en proceso: ${contexto.shipping_code}` : '');
const body = aiData.decision?.email_body || aiData.email_body || aiData.message || (is2500 ? 'Estimados, el siguiente pedido ha entrado en proceso de devolucion. Iniciamos seguimiento manual.' : '');

const emailTo = targetType === 'internal'
  ? 'alertas@sergi.com'
  : (clientCode.match(/^454160000[1-2]$/) ? 'cca.z2@cttexpress.com' : 'cca.z3@cttexpress.com');

return {
  should_notify: shouldNotify,
  target_type: targetType,
  email_subject: shouldNotify ? subject : '',
  email_body: shouldNotify ? body : '',
  ai_incident_detected: aiData.analysis?.detected_incident || aiData.detected_incident || (is2500 ? 'Devolucion' : 'N/A'),
  ai_justification: aiData.analysis?.justification || aiData.justification || (is2500 ? 'Paso 0: Estado terminal 2500 Detectado.' : 'Sin detalle'),
  h_en_estado: aiData.analysis?.hours_in_status || aiData.hours_in_status || 0,
  email_to: emailTo,
  numero_avisos: numeroAvisos,
  force_internal: forceInternal,
  is_2500: is2500,
  has_damage: hasDamage,
  notify_damage: hasDamage && String(contexto.shipping_status_code || '') !== '2000'
};

