const rows = $input.all();
const item = $('Calcular Estados y Horas').item.json;
const hoy = $now.toFormat('dd-MM-yyyy');
const ayer = $now.minus({days: 1}).toFormat('dd-MM-yyyy');

// Firestore get returns single doc (or empty if not found)
const doc = rows.length > 0 && rows[0].json.numero_envio ? rows[0].json : null;

const is2500 = String(item.shipping_status_code || '') === '2500';

let skip = false;
let forceInternal = false;
let numeroAvisos = 1;

if (doc) {
  const fecha = (doc.fecha_procesado || '').substring(0, 10);
  skip = !is2500 && fecha === hoy;
  forceInternal = !skip && (fecha === ayer || is2500);
  numeroAvisos = (doc.numero_avisos || 0) + 1;
} else {
  forceInternal = is2500;
}

return {
  json: {
    ...item,
    skip,
    force_internal: forceInternal,
    is_2500: is2500,
    numero_avisos: numeroAvisos
  }
};

try {
  const item = $('Loop: Processar 1 a 2').first().json;
  const history = $input.item.json;
  let events = [];

  if (history?.data?.shipping_history?.events) {
    events = history.data.shipping_history.events;
  } else if (Array.isArray(history)) {
    const data = history[0];
    if (data?.data?.shipping_history?.events) {
      events = data.data.shipping_history.events;
    }
  }

  const has1600 = events.some(e => e.code === '1600' || e.event_code === '1600');
  const hasDamage = events.some(e => {
    const code = e.code || e.event_code || '';
    const incidentCode = e.detail?.incident_type_code || '';
    return code.includes('6_INCT') || incidentCode.includes('6_INCT');
  });

  // ─── PARSEO Y FORMATO DEL HISTORIAL ─────────────────────────────────────────
  let parsedEvents = []; // { date: Date, code: string }
  let formattedHistory = 'Sin eventos disponibles';

  if (events.length > 0) {
    formattedHistory = events.map(e => {
      let date = e.event_date || e.item_event_date || '';
      let parsedDate = null;

      if (date) {
        try {
          const d = new Date(date);
          d.setHours(d.getHours() + 1); // UTC+1 Madrid
          parsedDate = d;
          date = d.toISOString().replace('T', ' ').substring(0, 16);
        } catch (x) {}
      }

      const code = e.code || e.event_code || 'N/A';
      const desc = e.description || e.event_description || '';
      const detailText = e.detail?.External_event_text || e.detail?.item_event_text || '';
      const incidentName = e.detail?.incident_type_name || '';
      const incidentCode = e.detail?.incident_type_code || '';
      const detail = incidentName ? `${detailText} [INCIDENCIA: ${incidentName} (${incidentCode})]`.trim() : detailText;

      if (parsedDate) {
        parsedEvents.push({ date: parsedDate, code, incidentCode });
      }

      return `${date} - [${code}] ${desc} (${detail})`;
    }).join('\n');
  }

  // ─── CÁLCULO DE HORAS LABORABLES ────────────────────────────────────────────
  // Lunes=1 ... Viernes=5, Sábado=6, Domingo=0
  function businessHours(startDate, endDate) {
    if (!startDate || !endDate || endDate <= startDate) return 0;
    let hours = 0;
    let cur = new Date(startDate.getTime());

    while (cur < endDate) {
      const dow = cur.getDay(); // 0=Dom, 6=Sab
      if (dow !== 0 && dow !== 6) {
        const y = cur.getFullYear(), m = cur.getMonth(), d = cur.getDate();
        const nextMidnight = new Date(y, m, d + 1);
        const seg = endDate < nextMidnight ? endDate : nextMidnight;
        hours += (seg - cur) / 3600000;
      }
      const y = cur.getFullYear(), m = cur.getMonth(), d = cur.getDate();
      cur = new Date(y, m, d + 1);
    }

    return parseFloat(hours.toFixed(1));
  }

  const now = new Date();

  const TRANSIT    = ['0900', '1000'];
  const DELIVERY   = ['1200', '1500'];
  const STATIONARY = ['1700', '1800'];
  const MANIFEST   = ['0000', '0030'];

  // TRÁNSITO: desde el primer 0900/1000, solo si no hay 1200/1500 posterior
  const firstTransit = parsedEvents.find(e => TRANSIT.includes(e.code));
  let transitHours = 0;
  if (firstTransit) {
    const hasDeliveryAfter = parsedEvents.some(
      e => e.code === '1500' && e.date > firstTransit.date
    );
    if (!hasDeliveryAfter) {
      transitHours = businessHours(firstTransit.date, now);
    }
  }

  // MANIFESTADO: desde primer 0000/0030, solo si aún no hay tránsito ni reparto
  const firstManifest = parsedEvents.find(e => MANIFEST.includes(e.code));
  let manifestHours = 0;
  if (firstManifest && !firstTransit) {
    manifestHours = businessHours(firstManifest.date, now);
  }

  // CICLO REPARTO: reset en cada 1000 después de 1200/1500
  // Regla: el ciclo empieza en el primer 1200/1500 del ciclo actual
  // Cada 1000 posterior a un 1200/1500 reinicia el ciclo
  let deliveryCycleStart = null;
  let inDelivery = false;
  for (const event of parsedEvents) {
    if (event.code === '1500') {
      deliveryCycleStart = event.date;
      inDelivery = true;
    } else if (event.code === '1200' && !inDelivery) {
      deliveryCycleStart = event.date;
      inDelivery = true;
    } else if (event.code === '1000' && inDelivery) {
      deliveryCycleStart = null;
      inDelivery = false;
    }
  }
  let deliveryHours = 0;
  if (deliveryCycleStart) {
    deliveryHours = businessHours(deliveryCycleStart, now);
  }

  // ESTACIONADO: desde el último 1700/1800
  const lastStationary = [...parsedEvents].reverse().find(e => STATIONARY.includes(e.code));
  let stationaryHours = 0;
  if (lastStationary) {
    stationaryHours = businessHours(lastStationary.date, now);
  }

  // ─── INCIDENCIAS ACTIVAS PRECALCULADAS ──────────────────────────────────────
  const INCIDENT_CODES = ['1600', '2400', '2600', '2700', '0600'];
  const TERMINAL_CODES = ['2500', '2300', '2310'];

  const lastEvent = parsedEvents[parsedEvents.length - 1];
  const isTerminal = lastEvent && TERMINAL_CODES.includes(lastEvent.code);

  // Una incidencia está activa si existe en el historial y NO hay 1500 ni Terminal después de ella
  let activeIncidentCode = null;
  for (const ev of parsedEvents) {
    if (INCIDENT_CODES.includes(ev.code)) {
      const has1500After = parsedEvents.some(e => e.code === '1500' && e.date > ev.date);
      // Regla CORE: si ya es terminal, no hay incidencia activa posible (resuelta por devolución/entrega/error)
      if (isTerminal) {
        activeIncidentCode = null;
      } else if (!has1500After) {
        // Solo es activa si no hay 1500 posterior Y no es terminal
        activeIncidentCode = ev.code;
      } else {
        // Si hay un 1500 posterior, se considera resuelta por el nuevo intento
        activeIncidentCode = null;
      }
    }
  }
  const hasActiveIncident = activeIncidentCode !== null;

  // ─── OUTPUT ─────────────────────────────────────────────────────────────────
  return {
    json: {
      ...item,
      status_history: events,
      formatted_history: formattedHistory,
      history_has_1600: has1600,
      has_damage: hasDamage,
      total_events: events.length,
      // Horas precalculadas para la IA
      transit_hours:    transitHours,
      manifest_hours:   manifestHours,
      delivery_hours:   deliveryHours,
      stationary_hours: stationaryHours,
      // Incidencia activa precalculada (NO recalcular en la IA)
      has_active_incident: hasActiveIncident,
      active_incident_code: activeIncidentCode || ''
    }
  };

} catch (error) {
  throw new Error(`[Code JS3] ${error.message}`);
}

// Expande el envío en N items, uno por bulto (item_code)
const shipment = $input.first().json;
const items = shipment.items || [];

if (items.length === 0) {
  return [{ json: { ...shipment, current_item_code: shipment.shipping_code + '001' } }];
}

return items.map(item => ({
  json: {
    ...shipment,
    current_item_code: item.item_code,
    current_item_other_code: item.item_other_code || null,
    current_item_weight: item.item_weight_declared || null
  }
}));

// Agrega todos los bultos del mismo envío en un único item
const all = $input.all();

if (all.length === 0) throw new Error('[Agregar Bultos] Sin items de entrada');

// Construir array de historiales por bulto
const bultosHistorial = all.map((it, i) => ({
  item_code: it.json.current_item_code || `bulto_${i + 1}`,
  formatted_history: it.json.formatted_history || 'Sin eventos',
  total_events: it.json.total_events || 0
}));

// Historial combinado para la IA (con cabecera por bulto)
const combinedHistory = bultosHistorial.map((b, i) =>
  `=== BULTO ${i + 1} (${b.item_code}) ===\n${b.formatted_history}`
).join('\n\n');

// Peor caso para horas (la IA ve el caso más crítico)
const maxOf = key => Math.max(...all.map(i => i.json[key] || 0));

// Incidencia: si algún bulto tiene incidencia activa, el envío la tiene
const hasActiveIncident = all.some(i => i.json.has_active_incident);
const activeItem = all.find(i => i.json.active_incident_code);
const activeIncidentCode = activeItem ? activeItem.json.active_incident_code : '';
const hasDamage = all.some(i => i.json.has_damage);

// Base: datos a nivel de envío del primer bulto
const base = all[0].json;

return {
  json: {
    ...base,
    // Historial por bulto (para guardar en Firebase)
    bultos_historial: bultosHistorial,
    bultos_historial_json: JSON.stringify(bultosHistorial),
    // Historial combinado para IA (reemplaza formatted_history)
    formatted_history: combinedHistory,
    // Horas peor caso
    transit_hours:    maxOf('transit_hours'),
    manifest_hours:   maxOf('manifest_hours'),
    delivery_hours:   maxOf('delivery_hours'),
    stationary_hours: maxOf('stationary_hours'),
    // Incidencia
    has_active_incident: hasActiveIncident,
    active_incident_code: activeIncidentCode,
    has_damage: hasDamage
  }
};

